using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using Assets.Scripts.Often;using Assets.Scripts.Sight.Surface.Pavilion;
public static class ReplayHierarchyValidation {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;
static void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;}
public static void Run(){try{Hierarchy();Overlay();File.WriteAllText("Logs/replay-hierarchy-result.txt","PASS "+checks+" checks");}catch(Exception e){File.WriteAllText("Logs/replay-hierarchy-result.txt",e.ToString());Debug.LogException(e);}}
static void Hierarchy(){var scene=UnityEditor.SceneManagement.EditorSceneManager.NewPreviewScene();var assets=ScriptableObject.CreateInstance<MatchReplayAssets>();var instance=typeof(MatchReplayAssets).GetField("instance",BindingFlags.Static|BindingFlags.NonPublic);var saved=instance.GetValue(null);instance.SetValue(null,assets);MatchReplayStateDisplay display=null;
try{var a=new GameObject("Aim parent");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(a,scene);a.transform.position=new Vector3(2,3,4);var b=new GameObject("Rest parent");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(b,scene);b.transform.position=new Vector3(-6,1,2);var cue=new GameObject("Cue");cue.transform.SetParent(a.transform,false);cue.transform.localPosition=Vector3.right;var renderer=cue.AddComponent<MeshRenderer>();renderer.forceRenderingOff=true;var camera=new GameObject("Camera").AddComponent<Camera>();UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(camera.gameObject,scene);var data=new MatchReplayPresentation();
using(var capture=new MatchReplayStateCapture(data)){capture.Capture(scene,camera,0);cue.transform.SetParent(b.transform,false);capture.Capture(scene,camera,1);cue.transform.SetParent(a.transform,false);capture.Capture(scene,camera,2);data.FlushPending();}
Check(data.events.Count(e=>e.kind=="visual-parent")==2,"Parent changes not captured");var nodes=data.events.Where(e=>e.kind=="visual-node").Select(e=>JsonUtility.FromJson<ReplayVisualNode>(e.value));int id=nodes.First(n=>n.name=="Cue").id;Check(!JsonUtility.FromJson<ReplayVisualState>(data.events.First(e=>e.kind=="visual-state"&&JsonUtility.FromJson<ReplayVisualState>(e.value).id==id).value).enabled,"forceRenderingOff lost");
foreach(string name in new[]{"RingCueBall","RingBall1","RingBall2","ChkBall","PointBig","BlindBack"}){int n=100+data.events.Count;data.events.Add(new MatchReplayPresentation.Event{kind="visual-node",value=JsonUtility.ToJson(new ReplayVisualNode{id=n,name=name,kind="transform"})});data.events.Add(new MatchReplayPresentation.Event{kind="visual-state",value=JsonUtility.ToJson(new ReplayVisualState{id=n,frame=0,active=true,enabled=true,scale=Vector3.one,rotation=Quaternion.identity})});}
var sorted=data.events.OrderBy(e=>e.time).ToArray();data.events.Clear();data.events.AddRange(sorted);
using(var stream=new MemoryStream()){data.Write(new BinaryWriter(stream));stream.Position=0;data=MatchReplayPresentation.Read(new BinaryReader(stream),3);}
display=new MatchReplayStateDisplay(a.transform,data,null);display.Apply(0);var target=display.Root.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Cue");Check(target.position==a.transform.position+Vector3.right,"Initial cue pose");display.Apply(1);Check(target.position==b.transform.position+Vector3.right,"Reparent cue pose");display.Apply(2);Check(target.position==a.transform.position+Vector3.right,"Return cue pose");display.Apply(0);Check(target.position==a.transform.position+Vector3.right,"Backward hierarchy reset");Check(display.Root.GetComponentsInChildren<Transform>(true).Where(t=>MatchReplayStateCapture.IsRemovedOverlay(t.name)).All(t=>!t.gameObject.activeInHierarchy),"Retired overlays visible");}
finally{display?.Dispose();instance.SetValue(null,saved);UnityEngine.Object.DestroyImmediate(assets);UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);}}
static void Overlay(){var host=new GameObject("Inactive physics");host.SetActive(false);var canvas=new GameObject("Toolbar canvas",typeof(RectTransform),typeof(Canvas));canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var panel=new GameObject("Practice Replay Controls",typeof(RectTransform));panel.transform.SetParent(canvas.transform,false);((RectTransform)panel.transform).sizeDelta=new Vector2(860,320);var events=new GameObject("Events",typeof(EventSystem));GameObject overlay=null;
try{var p=host.AddComponent<Assets.TutorialInfo.Scripts.TableSet06.Sight.Vital.PhysicsMng>();var type=p.GetType();var data=new MatchReplayPresentation{localSeat=0};data.frames.Add(Array.Empty<int>());var h=new InningScoreHistory();h.Reset(0);data.events.Add(new MatchReplayPresentation.Event{kind="inning-score",value=JsonUtility.ToJson(new ReplayInningEvent{frame=0,scores=h.Capture(),name0="Self",name1="Other"})});type.GetField("replayPresentation",flags).SetValue(p,data);type.GetField("replayPanel",flags).SetValue(p,(RectTransform)panel.transform);type.GetMethod("BuildReplayInnings",flags).Invoke(p,null);var view=(InningScoreView)type.GetField("replayInningView",flags).GetValue(p);overlay=view.gameObject;Canvas.ForceUpdateCanvases();typeof(InningScoreView).GetMethod("Update",flags).Invoke(view,null);view.IconButton.GetComponent<Button>().onClick.Invoke();typeof(InningScoreView).GetMethod("Update",flags).Invoke(view,null);Canvas.ForceUpdateCanvases();Check(view.IsOpen&&view.Panel.GetComponent<CanvasGroup>().blocksRaycasts,"Score icon does not open panel");Check(view.History.Columns==1&&view.transform.GetComponentsInChildren<TMPro.TMP_Text>(true).Any(t=>t.name=="Score 0"&&t.text=="0"),"Score table empty");var pos=RectTransformUtility.WorldToScreenPoint(null,view.IconButton.position);var results=new List<RaycastResult>();overlay.GetComponent<GraphicRaycaster>().Raycast(new PointerEventData(events.GetComponent<EventSystem>()){position=pos},results);var icon=view.IconButton.GetComponent<Graphic>();File.WriteAllText("Logs/inning-raycast.txt","screen="+Screen.width+","+Screen.height+" pos="+pos+" rect="+view.IconButton.rect+" root="+((RectTransform)overlay.transform).rect+" enabled="+icon.enabled+" active="+icon.isActiveAndEnabled+" raycast="+icon.raycastTarget+" cull="+icon.canvasRenderer.cull+" depth="+icon.depth+" canvas="+icon.canvas+" registry="+GraphicRegistry.GetGraphicsForCanvas(icon.canvas).Count+" hits="+results.Count+" ownHit="+icon.Raycast(pos,null));// Batch editor has no rendered Game View (native depth = -1); validate registration/filtering there.
Check(icon.depth<0 ? icon.raycastTarget&&!icon.canvasRenderer.cull&&icon.Raycast(pos,null)&&GraphicRegistry.GetGraphicsForCanvas(icon.canvas).Contains(icon) : results.Any(r=>r.gameObject==view.IconButton.gameObject),"Score icon raycast registration/filter failed");var before=view.IconButton.position;panel.transform.position+=Vector3.one*100;Canvas.ForceUpdateCanvases();Check(view.IconButton.position==before,"Toolbar drag moves inning overlay");}
finally{if(overlay)UnityEngine.Object.DestroyImmediate(overlay);UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(canvas);UnityEngine.Object.DestroyImmediate(events);}}
}
